window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-06-25"]={"date":"2026-06-25","dateKR":"2026년 6월 25일","dateEN":"25 June 2026","total":96,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. Top News","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"호르무즈 통항 급반등…미·이란 합의 후 유조선 운항 재개","src":"CNBC","date":"2026-06-19","kSum":"6월 18일 미국과 이란이 호르무즈 해협 상업항행 정상화에 합의하면서, 19일 하루에만 최소 20척의 유조선이 통항해 6월 2일 이후 최대치를 기록했다. 사우디 VLCC 3척이 AIS를 재가동하며 오만만으로 진입했다.","eSum":"After the 18 June US-Iran navigation deal, at least 20 tankers transited Hormuz on the 19th - the most since 2 June - and three Saudi VLCCs reactivated AIS in the Gulf of Oman.","kImp":"원유 톤마일과 탱커 운임에 직접 영향을 주는 핵심 변수다.","eImp":"A pivotal swing factor for crude ton-mile demand and tanker rates.","url":"https://www.cnbc.com/2026/06/19/iran-oil-tanker-traffic-strait-hormuz-gulf-vlcc.html"},{"code":"TOP","title":"이란, 해협 재봉쇄 선언…통항 하루 12척으로 급감","src":"Al Jazeera","date":"2026-06-22","kSum":"이스라엘의 레바논 공습에 대응해 이란이 호르무즈 해협을 다시 봉쇄한다고 선언하자 통항이 급감했다. 일요일 통항은 12척으로 전일 35척에서 크게 줄었다.","eSum":"Iran re-declared Hormuz shut over Israel's strikes on Lebanon, and transits collapsed to 12 vessels on Sunday from 35 the previous day.","kImp":"지정학 변동성이 운임·보험·항로를 동시에 흔든다.","eImp":"Geopolitical volatility hits rates, insurance and routing simultaneously.","url":"https://www.aljazeera.com/economy/2026/6/22/shipping-stalls-in-strait-of-hormuz-after-iran-declares-key-waterway-shut"},{"code":"TOP","title":"드루리 WCI 12% 상승…성수기 조기화로 운임 강세","src":"Ship Universe","date":"2026-06","kSum":"드루리 WCI가 6월 18일 40피트당 3,969달러로 12% 올랐다. 상하이-뉴욕은 15% 상승한 6,769달러, 상하이-로스앤젤레스는 10% 오른 5,142달러를 기록했다.","eSum":"Drewry's WCI rose 12% to $3,969/40ft on 18 June; Shanghai-New York up 15% to $6,769 and Shanghai-LA up 10% to $5,142.","kImp":"7월 관세 변경 전 선적 앞당기기와 조기 성수기가 운임을 끌어올린다.","eImp":"Front-loading ahead of July tariffs and an early peak season lift rates.","url":"https://www.shipuniverse.com/news/drewrys-latest-wci-climbs-again-as-early-peak-season-demand-keeps-container-pricing-firm/"},{"code":"TOP","title":"韓 조선 빅3, 1분기 합산 영업익 2.07조원 사상 최대","src":"Financial Today (파이낸셜투데이)","date":"2026-06","kSum":"HD한국조선해양·삼성중공업(Samsung Heavy)·한화오션(Hanwha Ocean) 빅3의 1분기 합산 영업이익이 2조702억원으로 사상 최대를 기록했고, 5월 말 누적 수주는 200억달러를 돌파했다.","eSum":"Korea's Big 3 - HD KSOE, Samsung Heavy, Hanwha Ocean - posted a record combined Q1 operating profit of KRW 2.07tn, with cumulative orders topping USD 20bn by end-May.","kImp":"13년 만의 조선 슈퍼사이클이 실적으로 현실화되고 있다.","eImp":"A 13-year shipbuilding super-cycle is now translating into earnings.","url":"https://www.ftoday.co.kr/news/articleView.html?idxno=359680"},{"code":"TOP","title":"로이즈리스트: 그림자선단 톤수 감소 전망…정상무역 복귀","src":"Lloyd's List","date":"2026-06-19","kSum":"이란산 원유 제재 완화 시 노후 그림자선단이 빠르게 해체 후보로 전락하고, 젊고 규정준수 선박이 호르무즈 화물을 더 실어나를 것으로 분석됐다. 일부 대형 선사는 중동 걸프에서 선박을 빼내고 있다.","eSum":"Lloyd's List sees shadow-fleet tonnage falling as Iran returns to open markets - ageing dark tankers becoming scrap candidates while younger compliant ships lift more cargo; major owners are exiting the Gulf.","kImp":"제재·항행 정상화가 탱커 선대 구조를 재편한다.","eImp":"Sanctions relief and reopened navigation reshape the tanker fleet structure.","url":"https://www.lloydslist.com/LL1157620/The-Week-in-Charts-Shadow-fleet-tanker-tonnage-to-fall--The-dry-bulk-guide-to-El-Nino--Major-shipowners-begin-exiting-vessels-from-MEG"},{"code":"TOP","title":"선원 임금 3년간 6.2% 인상 합의…간부 선원 부족 심화","src":"Maritime Executive","date":"2026-06","kSum":"ITF-JNG 합의로 선원 월 최저임금이 2026~2028년 6.2% 인상된다(AB 기준 673→715달러). 기관장·1등항해사·전자기관사 부족으로 간부 임금은 역사적 기준을 상회한다.","eSum":"An ITF-JNG deal raises the seafarer minimum wage 6.2% over 2026-2028 (AB $673->$715); shortages of Chief Engineers, Chief Officers and ETOs push senior pay above historical benchmarks.","kImp":"인력난이 운영비와 선원 확보 경쟁을 키운다.","eImp":"Crew scarcity drives up opex and competition for officers.","url":"https://www.maritime-executive.com/article/seafarers-win-6-wage-increase-over-three-years-despite-trade-uncertainties"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. Accidents","eTitle":"Section 2. Accidents","items":[{"code":"ACC","title":"싱가포르 파시르판장 앞 보급선 충돌 침몰…3명 사망","src":"SAFETY4SEA","date":"2026-06-12","kSum":"6월 12일 오전 싱가포르 파시르판장 터미널 앞에서 보급선이 상륙정과 충돌 후 침몰했다. 해경이 시신 3구를 수습했으며 사망자는 침몰한 보급선 선원으로 추정된다.","eSum":"A supply boat sank off Pasir Panjang Terminal, Singapore on the morning of 12 June after colliding with a landing craft; the Coast Guard recovered three bodies, believed to be the supply boat's crew.","kCause":"혼잡 수역 충돌(미흡한 견시·교신 추정).","eCause":"Collision in congested waters (likely lookout/communication lapses).","kLes":"혼잡 항만 수역에서 견시 강화와 VHF 사전 교신이 필수다.","eLes":"Enhanced lookout and proactive VHF coordination are vital in busy port waters.","url":"https://safety4sea.com/supply-vessel-sinks-after-collision-in-singapore-three-crew-dead/"},{"code":"ACC","title":"인도 파라디프항 석탄 양하 후 벌크선 화재","src":"Marine Insight","date":"2026","kSum":"인도 파라디프(Paradip)항에서 석탄 양하 작업 후 벌크선에서 화재가 발생했다. 석탄 자기발열 및 잔류 가스가 위험 요인으로 지목된다.","eSum":"A bulk carrier caught fire after coal loading/discharge operations at India's Paradip port, with coal self-heating and residual gases cited as risk factors.","kCause":"석탄화물 자기발열·가스 축적.","eCause":"Coal self-heating and gas accumulation.","kLes":"석탄 화물의 온도·가스 모니터링과 환기 관리가 핵심이다.","eLes":"Temperature/gas monitoring and ventilation control are key for coal cargoes.","url":"https://www.marineinsight.com/shipping-news/bulk-carrier-catches-fire-after-coal-loading-operation-in-indias-paradip-port/"},{"code":"ACC","title":"조디악 자동차운반선 태평양서 화재…선원 대피","src":"Lloyd's List","date":"2026","kSum":"조디악 매리타임(Zodiac Maritime)이 운항하는 자동차운반선에서 태평양 항해 중 화재가 발생해 선원이 대피했다. 차량 화물 화재의 진압 난이도가 다시 부각됐다.","eSum":"Crew were evacuated from a Zodiac Maritime vehicle carrier after a fire broke out in the Pacific, again highlighting the difficulty of fighting vehicle-cargo fires.","kCause":"차량 갑판 화재(전기차/화물 발화원 가능성).","eCause":"Vehicle-deck fire (possible EV/cargo ignition source).","kLes":"PCTC 화재 조기탐지·고정식 소화설비·대피 절차가 중요하다.","eLes":"Early detection, fixed firefighting and evacuation drills matter for PCTC fires.","url":"https://www.lloydslist.com/LL1153746/Crew-evacuated-from-Zodiac-Maritime-vehicle-carrier-in-Pacific-Ocean-after-fire"},{"code":"ACC","title":"인터카고 2026 벌크선 손실 보고서 발간","src":"INTERCARGO","date":"2026","kSum":"인터카고(INTERCARGO)가 2026년 벌크선 손실(Bulk Carrier Casualty) 보고서를 발간했다. 화물액상화·좌초·침수 등 주요 손실 원인과 인명피해 추세를 정리했다.","eSum":"INTERCARGO published its 2026 Bulk Carrier Casualty Report, summarising leading loss causes - cargo liquefaction, grounding, flooding - and fatality trends.","kCause":"복합 원인(액상화·구조·운항).","eCause":"Multiple causes (liquefaction, structural, operational).","kLes":"고체산적화물 수분·IMSBC 준수와 구조 점검이 손실 예방의 핵심이다.","eLes":"Cargo-moisture/IMSBC compliance and structural checks are central to loss prevention.","url":"https://www.intercargo.org/bulk-carrier-casualty-report-2026/"},{"code":"ACC","title":"2026년 6월 와이트섬 인근 영불 해협 선박 사고","src":"Wikipedia","date":"2026-06-16","kSum":"6월 16일 11시40분(UTC)경 와이트섬 남쪽 약 20해리 영해 밖에서 선박 사고가 발생했다. 관계당국이 사고 경위를 조사 중이다.","eSum":"An incident occurred around 11:40 UTC on 16 June about 20 nm south of the Isle of Wight, outside territorial waters; authorities are investigating.","kCause":"조사 진행 중(원인 미확정).","eCause":"Under investigation (cause undetermined).","kLes":"혼잡 해협의 통항분리·견시 준수가 재차 강조된다.","eLes":"TSS adherence and lookout discipline are reinforced in busy straits.","url":"https://en.wikipedia.org/wiki/2026_English_Channel_incident"}]},{"code":"PSC","type":"news","kTitle":"Section 3. Port State Control","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"DNV: 1분기 억류 64건…ISM·정비 결함이 주도","src":"DNV","date":"2026","kSum":"DNV 선대의 2026년 1분기 억류는 64건으로 전년 동기 52건보다 증가했다. 컨테이너·벌크·일반화물선이 83%를 차지했고 84%가 파리·도쿄 MOU에서 발생했다. ISM(15150)·정비(15109) 결함이 주요 억류 사유였다.","eSum":"DNV recorded 64 detentions in Q1 2026 (up from 52 a year earlier); container, bulk and general cargo made up 83%, with 84% in the Paris/Tokyo MoUs. ISM (15150) and maintenance (15109) deficiencies dominated.","kImp":"ISM 이행과 선체·장비 정비가 억류 회피의 핵심이다.","eImp":"ISM implementation and ship/equipment maintenance are key to avoiding detention.","url":"https://www.dnv.com/news/2026/port-state-control-q1-2026-detention-review-and-other-updates/"},{"code":"PSC","title":"파리 MOU 위원회, 신흥 해상 리스크 집중 대응","src":"SAFETY4SEA","date":"2026","kSum":"파리 MOU 위원회가 신흥 해상 안전 리스크를 점검하고 2026년 합동 집중점검(CIC)을 확정했다. 결함·억류 데이터 공유와 표적선박 선정 정교화를 추진한다.","eSum":"The Paris MoU Committee reviewed emerging maritime risks and confirmed the 2026 joint CIC, advancing deficiency/detention data sharing and refined ship targeting.","kImp":"표적선정 강화로 노후·저성과 선박의 점검 압박이 커진다.","eImp":"Sharper targeting increases inspection pressure on older/low-performing ships.","url":"https://safety4sea.com/paris-mou-committee-targets-emerging-maritime-risks/"},{"code":"PSC","title":"도쿄·파리 MOU, 선원임금·고용계약 합동 CIC 예고","src":"NorthStandard","date":"2026","kSum":"도쿄·파리 MOU가 선원 임금과 선원고용계약(SEA)에 대한 합동 집중점검(CIC)을 시행한다. 표준 질문지로 임금 지급·계약 적정성·근로조건 준수를 검증한다.","eSum":"Tokyo and Paris MoUs will run a joint CIC on crew wages and Seafarer Employment Agreements, using a standard questionnaire to verify wage payment, contract validity and working conditions.","kImp":"임금·계약 서류 정비와 기록 관리가 점검 통과의 관건이다.","eImp":"Wage/contract documentation and recordkeeping are critical to passing.","url":"https://north-standard.com/insights-and-resources/resources/news/tokyo-and-paris-mous-on-port-state-control"},{"code":"PSC","title":"도쿄·파리 MOU, 평형수관리협약 CIC 시행","src":"Tokyo MOU Kaikoumu","date":"2026","kSum":"도쿄·파리 MOU가 평형수관리협약(BWM Convention) 집중점검(CIC)을 시행한다. 평형수관리계획·기록부·처리설비 작동 등을 중점 검증한다.","eSum":"Tokyo and Paris MoUs are conducting a CIC on the Ballast Water Management Convention, focusing on the BWM plan, record book and treatment-system operation.","kImp":"BWMS 작동상태·기록부 정합성 점검이 필수다.","eImp":"Verifying BWMS operation and record-book consistency is essential.","url":"https://kaikoumu.zendesk.com/hc/en-us/articles/49521581526681--PSC-Concentrated-Inspection-Campaign-CIC-on-the-Ballast-Water-Management-Convention-to-be-conducted-under-the-Tokyo-MOU-and-Paris-MOU"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. Car Carriers (PCTC)","eTitle":"Section 4. Car Carriers (PCTC)","items":[{"code":"PCTC","title":"살라움라인, 중국에 LNG·암모니아레디 PCTC 2척 발주","src":"ship.energy","date":"2026","kSum":"살라움라인(Sallaum Lines)이 중국 샤먼조선(Xiamen Shipbuilding)에 8,600 CEU·5단 가변갑판 LNG 이중연료 PCTC 2척을 발주하고 추가 2척 옵션을 확보했다. 인도 시 LNG·VLSFO·LSMGO 운항이 가능하며 암모니아레디 표기를 갖춘다.","eSum":"Sallaum Lines ordered two 8,600-CEU, five-liftable-deck LNG dual-fuel PCTCs at Xiamen Shipbuilding with options for two more; ammonia-ready on delivery, running on LNG/VLSFO/LSMGO.","kImp":"친환경 선대 확충으로 IMO 2030·EU 규제에 대비한다.","eImp":"Greener fleet additions hedge IMO 2030 and EU rules.","url":"https://ship.energy/energy/sallaum-lines-orders-dual-fuel-lng-ammonia-ready-pctcs-in-china/"},{"code":"PCTC","title":"레이 카캐리어스, HD현대에 2.7억달러 PCTC 발주 연계","src":"Riviera","date":"2026","kSum":"레이 카캐리어스(Ray Car Carriers)가 HD현대(HD Hyundai)와 약 2억7천만달러 규모 PCTC 신조 계약에 연계된 것으로 보도됐다. 자동차운반선 선대 확장 수요가 이어진다.","eSum":"Ray Car Carriers has been linked to a ~US$270M PCTC newbuilding contract at HD Hyundai, reflecting continued fleet-expansion demand in car carriers.","kImp":"고선가에도 PCTC 신조 발주가 지속된다.","eImp":"PCTC newbuilding orders persist despite high prices.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/ray-car-carriers-linked-to-us270m-pctc-newbuilding-contract-at-hd-hyundai-88493"},{"code":"PCTC","title":"NOCC, 암모니아레디 PCTC 3번선 추가 발주","src":"The Loadstar","date":"2026","kSum":"NOCC가 암모니아레디 PCTC 신조 3번선을 발주목록에 추가했다. 무탄소 연료 전환을 염두에 둔 단계적 선대 현대화 전략이다.","eSum":"NOCC added a third ammonia-ready PCTC newbuild to its orderbook, part of a phased fleet-modernisation strategy geared to zero-carbon fuels.","kImp":"암모니아레디 발주가 PCTC 표준으로 자리잡는다.","eImp":"Ammonia-ready specs are becoming the PCTC norm.","url":"https://theloadstar.com/nocc-adds-third-ammonia-ready-pctc-newbuild-orderbook/"},{"code":"PCTC","title":"UECC, 친환경 PCTC 신조 2척 발주","src":"LNG Industry","date":"2026-03-04","kSum":"UECC가 친환경 사양의 PCTC 신조 2척을 발주했다. 단거리 유럽 항로의 배출 규제 대응을 위한 저탄소 추진 사양을 채택했다.","eSum":"UECC ordered a pair of eco-friendly PCTC newbuilds, adopting low-carbon propulsion to meet emissions rules on its short-sea European trades.","kImp":"역내 배출규제가 친환경 자동차선 발주를 견인한다.","eImp":"Regional emissions rules drive eco car-carrier ordering.","url":"https://www.lngindustry.com/small-scale-lng/04032026/uecc-orders-eco-friendly-pctc-newbuild-pair/"},{"code":"PCTC","title":"살라움라인, LNG 이중연료 자동차운반선 신조 인도","src":"MarineLink","date":"2026","kSum":"살라움라인이 LNG 이중연료 자동차운반선 신조 2척을 인도받았다. 신조 인도로 선대 평균 선령을 낮추고 연료 효율을 개선한다.","eSum":"Sallaum Lines took delivery of a pair of LNG dual-fuel car carrier newbuilds, lowering fleet age and improving fuel efficiency.","kImp":"신조 인도로 운영 효율과 규제 적합성이 향상된다.","eImp":"Newbuild deliveries improve efficiency and regulatory fit.","url":"https://www.marinelink.com/news/sallaum-takes-delivery-lng-dualfueled-car-540038"}]},{"code":"WW","type":"news","kTitle":"Section 5. Wallenius Wilhelmsen","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"WW, 자동차운송 계약에 4.2억달러 추가 연장","src":"Splash247","date":"2026-06","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)이 유럽 주요 완성차 업체와의 운송계약을 약 4억2천만달러 규모로 연장했다. 3년 연장(2028년 중반~2031년 중반)에 저배출 연료 사용이 포함된다.","eSum":"Wallenius Wilhelmsen extended a contract with a major European carmaker worth ~US$420M, a three-year extension (mid-2028 to mid-2031) including low-emission fuel use.","kImp":"장기계약 연장으로 운임·물량 가시성이 높아진다.","eImp":"Long-term renewal improves rate and volume visibility.","url":"https://splash247.com/wallenius-wilhelmsen-adds-420m-to-car-shipping-contract/"},{"code":"WW","title":"WW, 운송서비스 연장으로 5억달러 추가 확보","src":"MarineLink","date":"2026-06","kSum":"발레니우스 빌헬름센이 운송 서비스 연장 계약으로 약 5억달러를 추가 확보했다. 고정 계약 비중 확대로 수익 안정성을 강화하고 있다.","eSum":"Wallenius Wilhelmsen secured about US$500M from shipping-service extensions, strengthening earnings stability via a larger contracted base.","kImp":"계약 기반 확대가 시황 변동 완충 역할을 한다.","eImp":"A larger contract base cushions market volatility.","url":"https://www.marinelink.com/news/wallenius-wilhelmsen-bags-m-shipping-533232"},{"code":"WW","title":"WW, 2026년 전망 하향…벙커비 상승 반영","src":"Ship & Bunker","date":"2026-06","kSum":"발레니우스 빌헬름센이 벙커유 가격 상승을 반영해 2026년 실적 전망을 하향했다. 연료비 부담이 마진에 압력을 가하고 있다.","eSum":"Wallenius Wilhelmsen lowered its 2026 outlook to reflect rising bunker costs, with fuel expense pressuring margins.","kImp":"연료비가 자동차선 수익성의 핵심 변수다.","eImp":"Fuel cost is a key driver of car-carrier profitability.","url":"https://shipandbunker.com/news/emea/163558-wallenius-wilhelmsen-lowers-2026-outlook-as-bunker-costs-rise"},{"code":"WW","title":"WW, 2026 회계연도 가이던스 공시","src":"Wallenius Wilhelmsen","date":"2026","kSum":"발레니우스 빌헬름센이 2026 회계연도 전망과 2025년 갱신 가이던스를 거래소에 공시했다. 시황·연료·계약 갱신 전제를 반영한 실적 가이드를 제시했다.","eSum":"Wallenius Wilhelmsen issued a stock-exchange notice on its 2026 financial-year outlook and updated 2025 guidance, reflecting market, fuel and contract-renewal assumptions.","kImp":"공식 가이던스가 투자자 기대를 재설정한다.","eImp":"Official guidance resets investor expectations.","url":"https://www.walleniuswilhelmsen.com/stock-exchange-notice/wallenius-wilhelmsen-2026-financial-year-outlook-and-updated-2025-guidance"},{"code":"WW","title":"WW 1분기 조정 EBITDA 3.89억달러…순익 1.77억달러","src":"Wallenius Wilhelmsen","date":"2026-05","kSum":"발레니우스 빌헬름센의 1분기 조정 EBITDA는 3억8,900만달러로 전분기比 3% 감소했고 순이익은 1억7,700만달러로 안정적이었다. 매출은 12억5,300만달러였다.","eSum":"Wallenius Wilhelmsen's Q1 adjusted EBITDA was US$389M (-3% QoQ) with net profit stable at US$177M on revenue of US$1,253M.","kImp":"물류 호조가 해운 약세를 일부 상쇄했다.","eImp":"Strong logistics partly offset softer shipping.","url":"https://www.walleniuswilhelmsen.com/storage/images/Investor-relations/Wallenius-Wilhelmsen-Quarterly-report-Q1-2026.pdf"},{"code":"WW","title":"WW, 1년 단위 운송계약 신규 체결","src":"TradingView (Reuters)","date":"2026","kSum":"발레니우스 빌헬름센이 2026년부터 시작되는 1년 단위 신규 운송계약을 체결했다고 공시했다. 단기 계약으로 시황 변동에 유연하게 대응한다.","eSum":"Wallenius Wilhelmsen entered a new one-year shipping contract starting 2026, adding flexibility to respond to market swings.","kImp":"단·장기 계약 믹스로 리스크를 분산한다.","eImp":"A mix of short- and long-term deals diversifies risk.","url":"https://www.tradingview.com/news/reuters.com,2026:newsml_FWN3Y716T:0-wallenius-wilhelmsen-enters-one-year-shipping-contract-starting-2026/"},{"code":"WW","title":"WW, EUKOR 옵션 계약 수정…단기 부채 축소","src":"TipRanks","date":"2026-04","kSum":"발레니우스 빌헬름센과 HMG가 EUKOR 지분 풋·콜 옵션을 OCC(최소 50% 물량 약정) 유지 동안 행사하지 않기로 합의했다. 최초 행사 가능일은 2031년 1월 1일로, EUKOR 풋 부채는 8억5,100만달러로 감소했다.","eSum":"WW and HMG agreed the EUKOR put/call options cannot be exercised while the OCC commits >=50% of HMG volumes (earliest exercise 1 Jan 2031); EUKOR put liability fell to US$851M.","kImp":"지배구조·부채 불확실성이 완화됐다.","eImp":"Governance and liability uncertainty is reduced.","url":"https://www.tipranks.com/news/company-announcements/wallenius-wilhelmsen-revises-eukor-option-deal-cutting-near-term-liability"},{"code":"WW","title":"WW, 에퀴노르와 2년 바이오메탄올 공급 계약","src":"Equinor","date":"2026-03-11","kSum":"발레니우스 빌헬름센이 에퀴노르(Equinor)와 노르웨이산 매스밸런스 바이오메탄올을 안트베르펜·제브뤼헤에서 공급받는 2년 계약을 체결했다. ISCC EU 인증으로 CO2 95% 저감이 기대된다.","eSum":"Wallenius Wilhelmsen signed a two-year deal with Equinor for Norwegian mass-balanced bio-methanol delivered at Antwerp and Zeebrugge; ISCC-EU certified, ~95% CO2 cut.","kImp":"메탄올 신조의 연료 공급망을 선제 확보한다.","eImp":"Secures the fuel supply chain for methanol newbuilds.","url":"https://www.equinor.com/news/20260311-bio-methanol-agreement-wallenius-wilhelmsen"},{"code":"WW","title":"WW, 안트베르펜·제브뤼헤 바이오메탄올 벙커 확보","src":"SAFETY4SEA","date":"2026","kSum":"발레니우스 빌헬름센이 다가오는 이중연료 메탄올선을 위해 안트베르펜·제브뤼헤에서 바이오메탄올 벙커링을 2026년 말부터 받기로 했다. 항만 단위 친환경 연료 공급 체계를 구축한다.","eSum":"Wallenius Wilhelmsen will bunker bio-methanol at Antwerp and Zeebrugge from late 2026 for its upcoming dual-fuel methanol vessels, building port-level green-fuel supply.","kImp":"항만 벙커링 확보가 메탄올 운항의 전제다.","eImp":"Securing port bunkering underpins methanol operations.","url":"https://safety4sea.com/wallenius-wilhelmsen-signs-agreement-for-bio-methanol-in-antwerp-and-zeebrugge/"},{"code":"WW","title":"WW, 에퀴노르 2년 바이오메탄올 공급 상세 공개","src":"Manifold Times","date":"2026","kSum":"발레니우스 빌헬름센이 에퀴노르로부터 2년간 바이오메탄올 벙커유를 공급받는 계약의 세부 사항을 공개했다. 노르웨이 생산·유럽 인도 구조로 인증 연료를 안정 조달한다.","eSum":"Wallenius Wilhelmsen detailed its two-year Equinor bio-methanol bunker supply - produced in Norway, delivered in Europe - to secure certified fuel.","kImp":"장기 연료계약이 가격·공급 리스크를 줄인다.","eImp":"Long-term fuel contracts cut price and supply risk.","url":"https://www.manifoldtimes.com/news/wallenius-wilhelmsen-secures-two-year-bio-methanol-bunker-fuel-supply-from-equinor/"},{"code":"WW","title":"WW, 브레이크벌크 강화…벤트 부사장 승진","src":"Heavy Lift PFI","date":"2026-06-04","kSum":"발레니우스 빌헬름센이 산업 글로벌 영업조직을 신설하고 카르스텐 벤트(Carsten Wendt)를 EMEA 산업영업 부사장으로 승진시켰다. 미국 AI·전력망 수요로 변압기 등 고중량 화물 수요가 견조하다.","eSum":"Wallenius Wilhelmsen created an industrial global sales unit and promoted Carsten Wendt to VP industrial sales EMEA; H&H/breakbulk demand is solid, driven by US AI/grid transformers.","kImp":"고중량·브레이크벌크가 새로운 성장축으로 부상한다.","eImp":"High & heavy/breakbulk emerges as a new growth pillar.","url":"https://www.heavyliftpfi.com/news/2026/06/04/wendt-promoted-as-wallenius-wilhelmsen-strengthens-breakbulk-focus/"},{"code":"WW","title":"WW, 역대 최중량 단일 브레이크벌크 화물 운송","src":"Heavy Lift PFI","date":"2026","kSum":"발레니우스 빌헬름센이 역대 최중량 단일 브레이크벌크 화물 운송을 수행했다. RoRo 기반 고중량 운송 역량을 입증했다.","eSum":"Wallenius Wilhelmsen delivered its heaviest-ever single breakbulk piece, demonstrating its RoRo-based heavy-cargo capability.","kImp":"고중량 운송 역량이 프로젝트 화물 경쟁력을 높인다.","eImp":"Heavy-lift capability boosts project-cargo competitiveness.","url":"https://www.heavyliftpfi.com/projects/wallenius-wilhelmsen-delivers-its-heaviest-single-breakbulk-piece-ever/35147.article"},{"code":"WW","title":"코그니전트, WW 레거시 시스템·AI 현대화 추진","src":"StockTitan","date":"2026-02","kSum":"코그니전트(Cognizant)가 발레니우스 빌헬름센과 파트너십을 확대해 레거시 포트폴리오 현대화와 실용 AI 효율화를 지원한다. 통합 공급망 파트너로의 전환을 뒷받침한다.","eSum":"Cognizant expanded its partnership with Wallenius Wilhelmsen to modernise legacy portfolios and introduce practical AI efficiencies, supporting its shift to an integrated supply-chain partner.","kImp":"디지털 전환이 운영비 절감과 서비스 차별화를 견인한다.","eImp":"Digital transformation drives cost savings and service differentiation.","url":"https://www.stocktitan.net/news/CTSH/cognizant-to-provide-strategic-technology-services-for-wallenius-q47p4or67a5i.html"},{"code":"WW","title":"WW 실적·전망 트래커 업데이트","src":"Quartr","date":"2026","kSum":"발레니우스 빌헬름센(WAWI)의 실적·전망 요약이 업데이트됐다. 분기 실적, 가이던스, 투자자 일정 등 핵심 지표를 추적한다.","eSum":"An updated investor summary for Wallenius Wilhelmsen (WAWI) tracks quarterly results, guidance and investor-calendar items.","kImp":"투자자 지표 추적이 시장 기대 형성에 활용된다.","eImp":"Tracking investor metrics informs market expectations.","url":"https://quartr.com/companies/wallenius-wilhelmsen_4483"}]},{"code":"EE","type":"news","kTitle":"Section 6. Energy Efficiency","eTitle":"Section 6. Energy Efficiency","items":[{"code":"EE","title":"메탄올·암모니아, 무탄소 연료로 빠른 진전","src":"Global Maritime Forum","date":"2026","kSum":"글로벌 마리타임 포럼은 메탄올선 약 60척 운항·300척 이상 발주·20개 항만 그린메탄올 벙커링으로 초기 스케일에 진입했다고 평가했다. 암모니아는 개념검증 단계에 근접했다.","eSum":"The Global Maritime Forum says methanol has reached early scale - ~60 vessels operating, 300+ on order, ~20 ports bunkering green methanol - while ammonia nears proof of concept.","kImp":"연료 공급망 확충이 스케일업의 관건이다.","eImp":"Scaling the fuel supply chain is the key bottleneck.","url":"https://globalmaritimeforum.org/press/methanol-and-ammonia-progressing-rapidly-extra-push-needed-to-scale/"},{"code":"EE","title":"2026 그린연료 경쟁: LNG·메탄올·암모니아·원자력","src":"Ship Universe","date":"2026","kSum":"2026년 그린연료 경쟁이 LNG·메탄올·암모니아와 원자력 옵션으로 확산되고 있다. 암모니아 엔진 시험은 탱크-투-웨이크 배출 최대 95% 저감 가능성을 시사한다.","eSum":"The 2026 green-fuel race spans LNG, methanol, ammonia and the nuclear option; ammonia engine tests suggest tank-to-wake cuts of up to 95%.","kImp":"연료 선택이 신조·개조 투자 의사결정을 좌우한다.","eImp":"Fuel choice shapes newbuild and retrofit investment decisions.","url":"https://www.shipuniverse.com/the-great-green-fuel-race-in-2026-lng-methanol-ammonia-and-the-nuclear-option/"},{"code":"EE","title":"FuelEU Maritime, 6월 30일 적합증서·벌금 마감","src":"Lloyd's Register","date":"2026-06","kSum":"FuelEU Maritime 규정에 따라 선박은 2026년 6월 30일까지 적합서류(DoC)를 비치하고 벌금 납부를 완료해야 한다. 온실가스 집약도 목표 미달 시 페널티가 부과된다.","eSum":"Under FuelEU Maritime, ships must hold the Document of Compliance on board and complete penalty payments by 30 June 2026, with penalties for missing GHG-intensity targets.","kImp":"적합성 관리 미흡 시 즉각적 비용 부담이 발생한다.","eImp":"Poor compliance management triggers immediate cost exposure.","url":"https://www.lr.org/en/services/statutory-compliance/fueleu-regulation/"},{"code":"EE","title":"풍력보조추진, FuelEU서 최대 5% GHG 저감 인정","src":"bound4blue","date":"2026","kSum":"풍력보조추진이 선박 추진 에너지의 15% 이상을 담당하면 FuelEU Maritime 온실가스 집약도 계산에서 최대 5% 저감을 인정받는다. 윈드 솔루션의 규제 인센티브가 명확해지고 있다.","eSum":"Wind-assisted propulsion earns up to a 5% GHG-intensity reduction under FuelEU Maritime when it provides >=15% of propulsion energy, clarifying the regulatory incentive for wind solutions.","kImp":"풍력 보조가 규제 적합성과 연료비를 동시에 개선한다.","eImp":"Wind assistance improves both compliance and fuel costs.","url":"https://bound4blue.com/fueleu-maritime-compliance-with-wind/"},{"code":"EE","title":"EU ETS 해운 편입, FuelEU와 동반 적용","src":"ABS Eagle","date":"2026","kSum":"EU 배출권거래제(EU ETS)가 2024년부터 해운에 확대 적용되며 FuelEU Maritime와 함께 종합적 탈탄소 프레임워크를 형성한다. 탄소가격과 연료수요 압력이 병행된다.","eSum":"The EU ETS has extended to shipping since 2024 and works in tandem with FuelEU Maritime, forming a comprehensive decarbonisation framework combining carbon pricing and fuel-demand pressure.","kImp":"탄소비용 내재화가 항로·연료 전략을 바꾼다.","eImp":"Internalised carbon costs reshape route and fuel strategy.","url":"https://ww2.eagle.org/en/rules-and-resources/regulatory-updates/eu-ets-inclusion-of-maritime-emissions.html"},{"code":"EE","title":"RMI, 2030년 항만 그린메탄올·암모니아 공급 청사진","src":"RMI","date":"2026","kSum":"RMI는 항만이 2030년까지 그린메탄올·암모니아를 공급하기 위한 청사진 보고서를 발표했다. 항만 인프라·공급망·수요 신호의 단계적 정렬을 제안한다.","eSum":"RMI released a blueprint for how ports can supply green methanol and ammonia by 2030, proposing phased alignment of port infrastructure, supply chains and demand signals.","kImp":"항만 준비가 무탄소 연료 확산의 선결 조건이다.","eImp":"Port readiness is a precondition for zero-carbon fuel uptake.","url":"https://rmi.org/press-release/new-report-provides-a-blueprint-for-how-ports-can-supply-green-methanol-and-ammonia-by-2030/"},{"code":"EE","title":"DNV, FuelEU Maritime 적합 인사이트 제공","src":"DNV","date":"2026","kSum":"DNV가 FuelEU Maritime 적합 전략 인사이트를 제공한다. 풀링·바이오연료·풍력 보조 등 적합성 잔액 관리 방안을 정리했다.","eSum":"DNV provides FuelEU Maritime compliance insights, outlining options to manage the compliance balance - pooling, biofuels and wind assistance.","kImp":"적합성 잔액의 전략적 관리가 비용을 좌우한다.","eImp":"Strategic compliance-balance management drives cost outcomes.","url":"https://www.dnv.com/maritime/insights/topics/fueleu-maritime/"},{"code":"EE","title":"풍력보조추진 FuelEU 계산법, 정밀 검토 필요","src":"BetterSea","date":"2026","kSum":"풍력보조추진의 FuelEU 적합성 기여는 에너지 사용량 산정 방식에 따라 달라져, 계산법에 대한 정밀 검토가 필요하다는 분석이 제시됐다. 저연료 선박일수록 기준 에너지가 작아 효과가 달라진다.","eSum":"Analysis warns that wind-assisted propulsion's FuelEU benefit depends on how energy use is calculated and deserves a closer look, since lower-consumption ships have a smaller energy base.","kImp":"계산 방식 이해가 풍력 투자 ROI 평가에 필수다.","eImp":"Understanding the calculation is essential to assess wind-investment ROI.","url":"https://www.bettersea.tech/post/wind-assisted-propulsion-under-fueleu-maritime-why-the-calculation-deserves-a-closer-look"}]},{"code":"DIG","type":"news","kTitle":"Section 7. Digitalization","eTitle":"Section 7. Digitalization","items":[{"code":"DIG","title":"해상 사이버사고 2025년 103% 급증…스마트선박 표적","src":"SAFETY4SEA","date":"2026","kSum":"2025년 해상 사이버사고가 전년比 103% 급증했으며 DDoS·랜섬웨어·악성코드가 다수를 차지했다. CYTUR는 스마트선박이 표적이 되고 있다며 시큐어바이디자인 전환을 촉구했다.","eSum":"Maritime cyber incidents jumped 103% in 2025 - DDoS, ransomware and malware dominating - and CYTUR warned smart ships are under fire, urging a secure-by-design overhaul.","kImp":"연결성 확대가 공격면을 키워 OT 보안이 시급하다.","eImp":"Rising connectivity expands the attack surface, making OT security urgent.","url":"https://safety4sea.com/maritime-cyber-incidents-jumped-103-in-2025/"},{"code":"DIG","title":"2026 해상 사이버리스크, 운영 리스크로 격상","src":"Dryad Global","date":"2026","kSum":"2026년 해상 사이버리스크가 IT를 넘어 운영기술(OT)·선박시스템으로 확산되며 운영 리스크로 격상됐다. AI 기반 자율형 공격이 새로운 국면을 예고한다.","eSum":"Maritime cyber risk in 2026 has become an operational risk as threats spread beyond IT into OT and vessel systems, with AI-driven autonomous attacks signalling a new phase.","kImp":"사이버리스크가 안전·가동률에 직접 영향을 준다.","eImp":"Cyber risk now directly affects safety and uptime.","url":"https://channel16.dryadglobal.com/maritime-cyber-risk-in-2026"},{"code":"DIG","title":"AI 확산이 해운 사이버 공격 위험 키워","src":"Smart Maritime Network","date":"2026-03","kSum":"보고서에 따르면 AI 확산이 해운의 사이버 공격 위험을 키우고 있다. 공격 자동화·정교화로 방어 난도가 상승한다.","eSum":"A report finds AI is placing the maritime industry at greater risk of cyber-attack, as automation and sophistication raise the bar for defence.","kImp":"AI 양면성에 대응한 방어 투자가 필요하다.","eImp":"Defensive investment must address AI's double-edged nature.","url":"https://smartmaritimenetwork.com/2026/03/02/ai-is-placing-maritime-industry-at-greater-risk-of-cyber-attack-report/"},{"code":"DIG","title":"항행수역 디지털 트윈, e-내비게이션 길 연다","src":"IHO","date":"2026","kSum":"국제수로기구(IHO)는 항행수역 디지털 트윈이 e-내비게이션의 토대가 된다고 제시했다. 정밀 해도·실시간 데이터 연계로 항행 안전·효율을 높인다.","eSum":"The IHO outlines how a digital twin of navigable waters paves the way for e-navigation, improving safety and efficiency via precise charts and real-time data integration.","kImp":"데이터 표준화가 자율·지능형 항행의 전제다.","eImp":"Data standardisation underpins autonomous and intelligent navigation.","url":"https://iho.int/en/the-digital-twin-of-the-navigable-waters-paving-the-way-for-e-navigation"},{"code":"DIG","title":"2026 해상 사이버리스크: 선대·규제·보험사 대응","src":"Maritime Innovations","date":"2026","kSum":"2026년 해상 사이버리스크가 선대 운영·규제 준수·보험 인수 전반에 걸쳐 중요해지고 있다. 가시성·인증·책임소재 정립이 핵심 과제로 부상했다.","eSum":"Maritime cyber risk in 2026 matters across fleet operations, compliance and insurance underwriting, with visibility, certification and accountability emerging as key tasks.","kImp":"사이버 거버넌스가 보험·인증과 연계된다.","eImp":"Cyber governance is increasingly tied to insurance and certification.","url":"https://maritime-innovations.com/maritime-cyber-risk-2026/"}]},{"code":"TECH","type":"news","kTitle":"Section 8. Ship Manager Technical Team","eTitle":"Section 8. Ship Manager Technical Team","items":[{"code":"TECH","title":"스크러버 개조, 계획 부재 시 공기 지연 위험","src":"Riviera","date":"2026","kSum":"스크러버 개조는 통상 21~28일이 소요되며 계획 부재 시 지연이 잦다. 2026~27년 1만2천여 척이 검사 대상에 올라 수리조선소 특별검사가 몰릴 전망이다.","eSum":"Scrubber retrofits typically take 21-28 days and often slip without planning; with over 12,000 vessels due for survey in 2026-27, repair yards face a rush of special surveys.","kImp":"드라이도크 일정·자재 사전계획이 가동손실을 줄인다.","eImp":"Pre-planned dry-dock slots and materials cut off-hire losses.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/staying-on-top-of-the-scrubber-retrofit-56583"},{"code":"TECH","title":"탱커 수리조선소, 개조 작업 급증","src":"Riviera","date":"2026","kSum":"탱커 수리조선소가 개조 작업 급증을 경험하고 있다. 배출규제·연료전환 대응 개조 수요가 도크 가용성을 압박한다.","eSum":"Tanker repair yards are experiencing a flurry of retrofit activity as emissions and fuel-transition upgrades pressure dock availability.","kImp":"개조 수요 급증이 도크 확보 경쟁을 심화한다.","eImp":"Surging retrofit demand intensifies competition for dock slots.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/tanker-repair-yards-experience-a-flurry-of-retrofit-activity-55810"},{"code":"TECH","title":"스크러버, 초기 도입 선사가 트렌드 주도","src":"Riviera","date":"2026","kSum":"스크러버 시장에서 초기 도입 선사들이 사양·운영 표준을 주도하고 있다. 데이터 기반 운영 최적화가 개조 ROI를 결정한다.","eSum":"Early adopters are setting the trend in scrubbers, shaping specs and operating standards; data-driven optimisation determines retrofit ROI.","kImp":"운영 데이터 관리가 개조 투자 회수를 좌우한다.","eImp":"Operating-data management drives retrofit payback.","url":"https://www.rivieramm.com/news-content-hub/news-content-hub/early-adopters-set-the-trend-in-scrubbers-56220"},{"code":"TECH","title":"드라이도크 개조, 정비·탈탄소 트렌드 부상(MOL 사례)","src":"MOL Service","date":"2026","kSum":"선박 수리 도크에서 정비·개조·탈탄소 작업이 늘고 있으며 MOL 사례가 소개됐다. 계획정비·연료전환 개조·에너지절감장치(ESD) 설치가 도크 일정의 핵심으로 부상한다.","eSum":"Ship-repair docks see growing maintenance, retrofit and decarbonization work — illustrated by MOL cases — with planned maintenance, fuel-transition retrofits and energy-saving-device installs central to dock scheduling.","kImp":"드라이도크 통합 계획이 가동손실·비용을 줄인다.","eImp":"Integrated dry-dock planning cuts off-hire and cost.","url":"https://www.mol-service.com/blog/dry-dock-retrofit"}]},{"code":"HR","type":"news","kTitle":"Section 9. Marine HR","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"2026 선원 최저임금, ITF/ILO 새 기준 적용","src":"Seaplify","date":"2026","kSum":"2026년 선원 최저임금이 ITF/ILO 합의에 따라 인상 적용된다. AB 기준 월 최저임금이 단계적으로 오르며 MLC 2006이 이를 참조한다.","eSum":"Seafarer minimum wages for 2026 rise under new ITF/ILO rates, with the AB monthly floor stepping up and referenced by MLC 2006.","kImp":"최저임금 인상이 인건비 기준선을 끌어올린다.","eImp":"Minimum-wage increases lift the baseline for crew costs.","url":"https://blog.seaplify.com/seafarer-minimum-wage-2026/"},{"code":"HR","title":"선원 부족이 임금 상승 견인","src":"Marine Log","date":"2026","kSum":"간부 선원 부족이 임금 상승을 견인하고 있다. 기관장·1등항해사·전자기관사 등 핵심 직책의 보수가 빠르게 오른다.","eSum":"Crew shortages are driving up seafarer wages, with senior roles - Chief Engineers, Chief Officers, ETOs - seeing the fastest pay rises.","kImp":"인력난이 운영비·확보경쟁을 동시에 키운다.","eImp":"Scarcity raises both opex and the contest for talent.","url":"https://www.marinelog.com/news/crew-shortages-are-driving-up-seafarer-wages/"},{"code":"HR","title":"도쿄·파리 MOU 선원임금 CIC 베스트프랙티스","src":"SAFETY4SEA","date":"2026","kSum":"도쿄·파리 MOU의 선원임금·고용계약(SEA) 집중점검(CIC)에 대비한 베스트프랙티스 가이드가 제시됐다. 임금 지급·계약·근로조건 기록 정비를 강조한다.","eSum":"A best-practice guide for the Tokyo/Paris MoU CIC on crew wages and SEAs highlights proper documentation of wage payment, contracts and working conditions.","kImp":"임금·계약 기록 관리가 PSC 리스크를 줄인다.","eImp":"Wage/contract recordkeeping reduces PSC risk.","url":"https://safety4sea.com/cm-cic-on-crew-wages-and-seafarer-employment-agreement-a-best-practice-guide/"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ","eTitle":"Section 10. HSEQ","items":[{"code":"HSEQ","title":"육상 리더십이 선상 안전문화를 좌우","src":"SAFETY4SEA","date":"2026","kSum":"2026 SAFETY4SEA 리마솔 포럼에서 육상 리더십의 질이 선상 안전문화를 근본적으로 형성한다는 점이 강조됐다. 일관된 메시지와 자원지원이 핵심으로 지목됐다.","eSum":"At the 2026 SAFETY4SEA Limassol Forum, speakers stressed that the quality of shore leadership fundamentally shapes onboard safety culture, with consistent messaging and resourcing key.","kImp":"경영진의 안전 우선순위가 현장 행동을 바꾼다.","eImp":"Management's safety priorities change frontline behaviour.","url":"https://safety4sea.com/cm-effective-leadership-ashore-improves-safety-culture-onboard/"},{"code":"HSEQ","title":"교훈: 밀폐구역 출입 통제를 강화하라","src":"SAFETY4SEA","date":"2026","kSum":"사고 교훈으로 밀폐구역 출입 통제 강화가 제시됐다. 진입 전 가스측정·허가서·감시인 배치 등 절차 준수가 인명사고를 막는 핵심이다.","eSum":"A lessons-learned note urges enhanced control over enclosed-space entry - pre-entry gas testing, permits and a posted attendant are central to preventing fatalities.","kImp":"비가시 위험에 대한 절차 준수가 생명을 지킨다.","eImp":"Procedural discipline against unseen hazards saves lives.","url":"https://safety4sea.com/lessons-learned-enhance-the-control-over-enclosed-space-entry/"},{"code":"HSEQ","title":"교훈: 더 안전한 계류로 인명을 지켜라","src":"SAFETY4SEA","date":"2026","kSum":"계류 작업 중 스냅백 존 회피와 안전한 위치 선정의 중요성이 재차 강조됐다. 라인 장력·배치 관리와 교육이 계류사고를 줄인다.","eSum":"Safer mooring guidance reiterates avoiding snap-back zones and choosing safe positions; managing line tension/layout and training reduces mooring casualties.","kImp":"계류 위험구역 인식과 절차가 부상을 예방한다.","eImp":"Awareness of mooring danger zones and procedure prevents injuries.","url":"https://safety4sea.com/cm-saving-lives-through-safer-mooring/"}]},{"code":"KR","type":"news","kTitle":"Section 11. Korean Shipping Market","eTitle":"Section 11. Korean Shipping Market","items":[{"code":"KR","title":"조선 빅3 동반 강세…수주 기대감 확산","src":"CBC News (씨비씨뉴스)","date":"2026","kSum":"한화오션(Hanwha Ocean)·삼성중공업(Samsung Heavy)·HD현대중공업(HD Hyundai Heavy)이 수주 기대감에 동반 강세를 보였다. 친환경 선박 전환과 방산 성장 기대가 매수세를 유인했다.","eSum":"Hanwha Ocean, Samsung Heavy and HD Hyundai Heavy rose together on order expectations, drawing buying on green-ship transition and defense growth hopes.","kImp":"수주 모멘텀이 조선주 전반의 투자심리를 견인한다.","eImp":"Order momentum drives sentiment across shipbuilding stocks.","url":"https://www.cbci.co.kr/news/articleView.html?idxno=582566"},{"code":"KR","title":"현대글로비스, 하반기 실적 우상향 기대","src":"In The News (인더리포트)","date":"2026","kSum":"자동차운반선 시황 호조와 컨테이너 운임 상승으로 현대글로비스(Hyundai Glovis)의 하반기 실적이 우상향할 가능성이 크다고 분석됐다. 운송 섹터 기대가 커지고 있다.","eSum":"Strong car-carrier markets and rising container rates point to upside for Hyundai Glovis in H2, lifting expectations across the transport sector.","kImp":"PCTC·컨테이너 동반 강세가 물류기업 실적을 끌어올린다.","eImp":"Concurrent PCTC and box strength boost logistics earnings.","url":"https://www.inthenews.co.kr/news/article.html?no=87539"},{"code":"KR","title":"HMM 매각, 운임 변동성 속 장기화 전망","src":"Shipping News Net (쉬핑뉴스넷)","date":"2026","kSum":"트럼프발 운임 변동성 속에서 HMM 매각이 장기화될 것이라는 관측이 제기됐다. 시황 불확실성이 매각 가격·시점에 영향을 준다.","eSum":"Amid Trump-driven rate volatility, HMM's sale is expected to take a long time, with market uncertainty affecting price and timing.","kImp":"매각 불확실성이 국적선사 전략에 변수로 작용한다.","eImp":"Sale uncertainty is a wildcard for the national carrier's strategy.","url":"https://www.shippingnewsnet.com/news/articleView.html?idxno=64090"},{"code":"KR","title":"HMM, 美 파산 생활용품업체로부터 피소","src":"The Guru (더구루)","date":"2026","kSum":"HMM이 파산한 미국 대형 생활용품업체로부터 화물 운송 지연·부당 운임을 이유로 피소됐다. 운임 분쟁이 법적 리스크로 비화했다.","eSum":"HMM was sued by a bankrupt large US household-goods firm alleging shipping delays and unfair freight, turning a rate dispute into legal risk.","kImp":"운임 분쟁이 선사 법적·평판 리스크로 확대된다.","eImp":"Freight disputes expand into legal and reputational risk for carriers.","url":"https://www.theguru.co.kr/news/article.html?no=96536"}]},{"code":"INS","type":"news","kTitle":"Section 12. Marine Insurance (P&I / H&M)","eTitle":"Section 12. Marine Insurance (P&I / H&M)","items":[{"code":"INS","title":"로이즈, 호르무즈 전쟁위험 신규 컨소시엄 출범","src":"Lloyd's","date":"2026-06-19","kSum":"로이즈가 호르무즈 해협 통항 선박·화물에 추가 전쟁위험 인수능력을 제공하는 신규 컨소시엄을 출범했다. 처브(Chubb) 주간사로 선체·P&I 각 2억달러, 화물 2억달러 능력을 제공한다.","eSum":"Lloyd's launched a new market consortium providing extra marine war-risk capacity for Hormuz transits - Chubb as lead, offering up to US$200M each for hull and P&I plus US$200M for cargo.","kImp":"민간 인수능력 보강이 통항 재개를 뒷받침한다.","eImp":"Added private capacity supports a resumption of transits.","url":"https://www.lloyds.com/insights/media-centre/press-releases/press-release-19062026"},{"code":"INS","title":"호르무즈 전쟁보험 경색…중동전 격화 반영","src":"S&P Global","date":"2026-03","kSum":"중동 전쟁 격화로 호르무즈 해협 전쟁보험 인수가 사실상 고갈됐다고 S&P 글로벌이 보도했다. 인수 거부와 보험료 급등이 동시에 나타났다.","eSum":"Marine war insurance for Hormuz dried up as Middle East conflict intensified, with both withdrawal of cover and soaring premiums.","kImp":"보험 가용성 위축이 항행·무역에 직접 타격을 준다.","eImp":"Shrinking cover availability directly hits navigation and trade.","url":"https://www.spglobal.com/market-intelligence/en/news-insights/articles/2026/3/marine-war-insurance-for-hormuz-dries-up-as-middle-east-war-intensifies-99283143"},{"code":"INS","title":"전쟁위험 보험료, 선가의 2.5~3%…평시의 25~30배","src":"House of Saud","date":"2026-06","kSum":"호르무즈 위험 완화에도 전쟁위험 보험료는 항차당 선가의 2.5~3%로 평시 기준(0.1%)의 25~30배 수준을 유지하고 있다. 시장은 위험 완화를 즉시 반영하지 않는다.","eSum":"Despite some de-escalation, war-risk premiums remain at 2.5-3% of hull value per voyage - 25-30x the 0.1% pre-conflict baseline - as the market lags risk improvement.","kImp":"보험료 경직성이 운임·연료 비용 부담을 가중한다.","eImp":"Sticky premiums add to freight and fuel cost burdens.","url":"https://houseofsaud.com/hormuz-downgrade-insurance-market-gap/"},{"code":"INS","title":"WEF: 중동전, 정부를 '최후 보험자'로 만들다","src":"World Economic Forum","date":"2026-04","kSum":"세계경제포럼은 호르무즈 전쟁보험 중단이 정부를 사실상 최후 보험자로 만들고 있다고 분석했다. 국가 보증·재보험 개입 필요성이 부각된다.","eSum":"The WEF analyses how the halt in Hormuz war-risk insurance is turning governments into insurers of last resort, highlighting the need for state guarantees and reinsurance backstops.","kImp":"공적 백스톱이 해상무역 연속성의 안전판이 된다.","eImp":"Public backstops become a safety net for trade continuity.","url":"https://www.weforum.org/stories/2026/04/how-middle-east-war-turning-governments-into-insurers-last-resort/"},{"code":"INS","title":"LMA: 통항 감소는 보험가용성 아닌 안전우려 탓","src":"LMA","date":"2026-06","kSum":"런던보험시장협회(LMA)는 호르무즈 통항 감소의 주원인이 보험 가용성이 아니라 안전 우려라고 밝혔다. 위험구역 담보는 시장에서 제공되고 있다는 입장이다.","eSum":"The LMA states that reduced Strait of Hormuz traffic is driven by safety concerns rather than insurance availability, noting cover for high-risk areas is being offered.","kImp":"리스크 인식이 보험보다 통항 결정을 좌우한다.","eImp":"Risk perception, more than insurance, drives transit decisions.","url":"https://lmalloyds.com/safety-concerns-not-insurance-availability-driving-reduced-vessel-traffic-in-the-strait-of-hormuz/"},{"code":"INS","title":"하우든, 호르무즈 전쟁위험 담보 제공 지속","src":"Howden Group","date":"2026","kSum":"하우든(Howden)은 호르무즈 해협 고위험 구역 선박에 전쟁위험 담보를 제공하는 시장이 작동 중이라고 밝혔다. 가격은 높지만 인수능력은 존재한다는 설명이다.","eSum":"Howden says the marine war market is offering cover for vessels in the high-risk Strait of Hormuz area - capacity exists, albeit at elevated pricing.","kImp":"고가라도 담보 존재가 통항 옵션을 유지시킨다.","eImp":"Cover, even if costly, keeps transit options open.","url":"https://www.howdengroupholdings.com/insights/strait-of-hormuz-marine-war-market-offering-cover-for-vessels-in-high-risk-areas"},{"code":"INS","title":"걸프 전쟁위험 담보 취소…에너지 비용 우려","src":"Al Jazeera","date":"2026-03-03","kSum":"보험사들이 페르시아만 전쟁위험 담보를 취소하면서 에너지 비용 상승 우려가 제기됐다. P&I 클럽들도 3월 5일자로 걸프 전쟁위험 담보를 취소했다.","eSum":"Insurers cancelled Gulf war-risk cover, raising fears of higher energy costs; P&I clubs also withdrew Persian Gulf war-risk cover effective 5 March.","kImp":"담보 취소가 에너지·운임 인플레로 전이된다.","eImp":"Cover withdrawal feeds into energy and freight inflation.","url":"https://www.aljazeera.com/economy/2026/3/3/maritime-insurers-cancel-war-risk-cover-in-gulf-will-it-spike-energy-cost"}]},{"code":"VET","type":"news","kTitle":"Section 13. Vetting / RightShip","eTitle":"Section 13. Vetting / RightShip","items":[{"code":"VET","title":"라이트십, 4월1일부터 노후 벌크선 점검 의무 강화","src":"RightShip","date":"2026","kSum":"2026년 4월 1일부터 선령 12년 이상 벌크·일반화물선이 유효한 라이트십(RightShip) 점검이 없으면 안전점수가 5점 만점 2점으로 강등돼 주요 화주의 용선에서 사실상 배제된다.","eSum":"From 1 April 2026, dry-bulk and general-cargo ships aged 12+ without a valid RightShip inspection are downgraded to a Safety Score of 2/5, effectively blocking nominations by major charterers.","kImp":"점검 미보유 선박의 상업적 배제 위험이 커진다.","eImp":"Ships lacking inspections face growing commercial exclusion.","url":"https://marineinspection.app/blog/rightship-vessel-vetting-safety-score-inspection-guide-bulk-carriers"},{"code":"VET","title":"라이트십, 7월1일 3단계…선령 11년+ 점검 요구","src":"RightShip","date":"2026","kSum":"라이트십 점검 요건 3단계가 2026년 7월 1일 시행돼 선령 11년 이상 선박도 유효한 점검을 요구받는다. 안전점수·PSC 결함 가중·GHG 등급이 종합 평가된다.","eSum":"RightShip's Phase 3 from 1 July 2026 extends inspection requirements to vessels aged 11+, with Safety Score, severity-weighted PSC deficiencies and GHG Rating jointly assessed.","kImp":"점검 요건 단계적 확대가 선대 관리 부담을 키운다.","eImp":"Phased inspection rules increase fleet-management burden.","url":"https://help.rightship.com/en/articles/rightships-safety-score-and-vessel-vetting"},{"code":"VET","title":"라이트십 GHG 등급, 상업적 차별화 요소로 부상","src":"RightShip","date":"2026","kSum":"라이트십 GHG 등급(A~G)이 EU ETS·FuelEU 확대 속에서 단순 환경배지를 넘어 상업적 차별화 요소로 부상하고 있다. ESG 화주의 용선 기준에 반영된다.","eSum":"RightShip's GHG Rating (A-G) is becoming a commercial differentiator - not just an environmental badge - as EU ETS and FuelEU expand and ESG charterers weigh it in chartering.","kImp":"GHG 등급이 용선 경쟁력과 직결된다.","eImp":"The GHG Rating ties directly to chartering competitiveness.","url":"https://rightship.com/solutions/charterer/safety-score"},{"code":"VET","title":"SIRE 2.0, 사진 중심·디지털 점검 정착","src":"OCIMF SIRE 2.0","date":"2026","kSum":"OCIMF SIRE 2.0 탱커 점검이 사진 중심·디지털 기록 체계로 정착되고 있다. 점검당 약 100개 맞춤 질문과 표준 사진 가이드라인이 적용된다.","eSum":"OCIMF SIRE 2.0 tanker inspections are bedding in as a photo-centric, digitally recorded regime, with ~100 tailored questions per inspection and standardised photo guidelines.","kImp":"사진·디지털 증빙 준비가 점검 통과의 변수다.","eImp":"Photo and digital evidence readiness is now a passing factor.","url":"https://marineinspection.app/blog/sire-2-0-inspection-guide-ocimf-tanker-vetting-programme-2026"}]},{"code":"CLASS","type":"news","kTitle":"Section 14. Classification Societies","eTitle":"Section 14. Classification Societies","items":[{"code":"CLASS","title":"IACS 통일요건 E26/E27, 사이버복원력 적용 본격화","src":"IACS","date":"2026","kSum":"국제선급연합회(IACS)의 사이버복원력 통일요건 UR E26(선박 전체)·E27(선내 시스템·장비)이 2024년 7월 1일 이후 건조계약 신조선에 적용된다. 선급들은 설계·시운전 단계 검증을 강화하고 있다.","eSum":"IACS Unified Requirements UR E26 (ship) and E27 (onboard systems/equipment) on cyber resilience apply to newbuilds contracted on/after 1 July 2024, with classes tightening design- and trial-stage verification.","kImp":"사이버복원력이 신조 선급검사의 핵심 항목으로 부상한다.","eImp":"Cyber resilience becomes a core item in newbuild class survey.","url":"https://iacs.org.uk/news/iacs-ur-e26-and-e27-press-release"},{"code":"CLASS","title":"ClassNK, IACS UR E26 사이버복원력 가이드라인 발간","src":"ClassNK","date":"2026","kSum":"일본선급(ClassNK)이 IACS UR E26 요건을 설명하는 '선박 사이버복원력 가이드라인'을 발간했다. 요구 조치와 적합 절차를 정리해 선사·조선소의 이행을 지원한다.","eSum":"ClassNK released 'Guidelines for Cyber resilience of ships', explaining IACS UR E26 requirements and the actions needed, supporting owner/yard compliance.","kImp":"선급 가이드라인이 신조·기존선 사이버 적합을 견인한다.","eImp":"Class guidelines drive cyber compliance for new and existing ships.","url":"https://www.hellenicshippingnews.com/classnk-releases-guidelines-for-cyber-resilience-of-ships-explaining-iacs-ur-e26-requirements-and-necessary-actions/"},{"code":"CLASS","title":"DNV, 기술·규제 뉴스로 2026 규칙 개정 안내","src":"DNV","date":"2026","kSum":"DNV가 기술·규제 뉴스를 통해 2026년 선급규칙 개정과 발효 일정을 안내하고 있다. 구조·기관·디지털·연료 관련 요건 갱신이 신조·개조 설계에 반영된다.","eSum":"DNV's technical & regulatory news channel sets out 2026 class-rule amendments and entry-into-force dates, with structural, machinery, digital and fuel updates feeding into newbuild/retrofit design.","kImp":"규칙 개정 추적이 설계·검사 일정 관리에 필수다.","eImp":"Tracking rule changes is essential for design and survey scheduling.","url":"https://www.dnv.com/maritime/technical-regulatory-news/"}]},{"code":"COMM","type":"news","kTitle":"Section 15. Commercial / Chartering Market","eTitle":"Section 15. Commercial / Chartering Market","items":[{"code":"COMM","title":"발틱운임지수, 케이프 주도로 반등","src":"Trading Economics","date":"2026-06","kSum":"발틱건화물운임지수(BDI)가 케이프사이즈 선형 강세에 힘입어 6월 12일 이후 최고치인 2,722선으로 반등했다. 다만 일부 세션에서는 전반적 약세도 혼재됐다.","eSum":"The Baltic Dry Index rebounded to around 2,722 - its highest since 12 June - led by the capesize segment, though some sessions showed broad-based weakness.","kImp":"대형선 강세가 건화물 시황 회복을 견인한다.","eImp":"Capesize strength leads the dry-bulk recovery.","url":"https://tradingeconomics.com/commodity/baltic"},{"code":"COMM","title":"드루리 주간 업데이트: 7월 관세 전 선적 앞당기기","src":"Drewry","date":"2026-06","kSum":"드루리 주간 컨테이너 업데이트에 따르면 7월 관세 변경 전 선적 앞당기기와 할증 도입으로 운임이 추가 상승했다. 향후 수주간 추가 상승이 전망된다.","eSum":"Drewry's weekly update notes rates rose further on front-loading ahead of July tariff changes and surcharge introductions, with more increases expected in coming weeks.","kImp":"관세 캘린더가 단기 운임 사이클을 좌우한다.","eImp":"The tariff calendar drives the short-term rate cycle.","url":"https://www.drewry.co.uk/supply-chain-advisors/world-container-index-weekly-update/container-shipping1"},{"code":"COMM","title":"드루리 결항 추적: 성수기 수급 관리 강화","src":"Drewry","date":"2026-06","kSum":"드루리 결항(blank sailing) 추적에 따르면 선사들이 성수기 수요와 공급 균형을 위해 결항을 조정하고 있다. 수급 관리가 운임 방어의 핵심 수단으로 활용된다.","eSum":"Drewry's cancelled-sailings tracker shows carriers adjusting blank sailings to balance peak-season demand and supply, using capacity management to defend rates.","kImp":"결항 운영이 운임 변동성을 조절한다.","eImp":"Blank-sailing management moderates rate volatility.","url":"https://www.drewry.co.uk/supply-chain-advisors/supply-chain-expertise/cancelled-sailings-tracker"},{"code":"COMM","title":"마스코트오션, 케이프사이즈 시장 진입","src":"Splash247","date":"2026","kSum":"마스코트오션(Mascot Ocean)이 케이프사이즈 시장에 진입했다. 대형 건화물선 수요 기대를 반영한 선대 확장 움직임이다.","eSum":"Mascot Ocean entered the capesize segment, a fleet-expansion move reflecting expectations of demand for large dry-bulk carriers.","kImp":"신규 진입이 대형선 시장 경쟁을 키운다.","eImp":"New entry adds competition in the large-bulker market.","url":"https://splash247.com/mascot-ocean-enters-the-cape-segment/"}]},{"code":"GEO","type":"news","kTitle":"Section 16. Geopolitical Chokepoints","eTitle":"Section 16. Geopolitical Chokepoints","items":[{"code":"GEO","title":"컨테이너 선사, 후티 위협에 홍해 우회 지속","src":"Seatrade Maritime","date":"2026","kSum":"컨테이너 선사들이 후티 위협을 피해 홍해를 우회하고 희망봉 항로를 유지하고 있다. 수에즈 정상화 시도는 시범적 수준에 머문다.","eSum":"Container lines continue rerouting from the Red Sea to avoid the Houthi threat, keeping the Cape of Good Hope route; Suez normalisation attempts remain tentative.","kImp":"우회 장기화가 톤마일·운임을 떠받친다.","eImp":"Prolonged rerouting supports ton-mile demand and rates.","url":"https://www.seatrade-maritime.com/containers/shipping-lines-reroute-from-red-sea-avoiding-houthi-threat"},{"code":"GEO","title":"수에즈 통항, 회복 시도에도 의문 남아","src":"AJOT","date":"2026","kSum":"수에즈 운하 통항이 일부 회복을 시도하고 있으나, 안보 불확실성으로 표준 항로로 복귀하기에는 의문이 남는다. 일부 대형 선사가 시범 통항에 나섰다.","eSum":"Suez Canal traffic is attempting a return, but security uncertainty leaves questions over restoring it as a standard corridor; some majors have begun trial transits.","kImp":"안보 변수에 따라 항로 선택이 반복적으로 바뀐다.","eImp":"Routing flips repeatedly with security conditions.","url":"https://www.ajot.com/insights/full/ai-suez-canal-traffic-returnswith-questions"},{"code":"GEO","title":"파나마운하, 엘니뇨 워치로 2026 수위 리스크","src":"Rio Times","date":"2026","kSum":"2026년 중반 엘니뇨 발생 가능성에 NOAA가 워치를 발령하면서, 중간 강도라도 파나마운하의 우기 수위 가용성이 빠듯해질 수 있다는 우려가 제기됐다.","eSum":"With NOAA issuing an El Nino Watch for mid-2026, even a moderate event could tighten Panama Canal water availability during the wet season.","kImp":"수위 리스크가 통항 슬롯·흘수 제한을 좌우한다.","eImp":"Water risk drives transit-slot and draft limits.","url":"https://www.riotimesonline.com/panama-canal-2026-guide/"},{"code":"GEO","title":"유조선 CEO: 합의 시 호르무즈 통항 급증 전망","src":"CNBC","date":"2026-06-11","kSum":"프론트라인 CEO는 미·이란 합의가 이뤄지면 호르무즈 통항이 빠르게 증가할 것이라고 전망했다. 통항 정상화 기대가 탱커 시황 심리를 자극한다.","eSum":"Frontline's CEO said Hormuz traffic would increase quickly if the US and Iran reached a deal, with normalisation hopes lifting tanker-market sentiment.","kImp":"합의 진전이 탱커 운임 기대를 좌우한다.","eImp":"Deal progress sways tanker-rate expectations.","url":"https://www.cnbc.com/2026/06/11/iran-strait-hormuz-oil-tanker-traffic-frontline.html"},{"code":"GEO","title":"UANI, 6월 4일 이란 전쟁 해운 업데이트","src":"UANI","date":"2026-06-04","kSum":"UANI는 6월 4일 이란 전쟁 관련 해운 동향 업데이트를 발표했다. 호르무즈 인근 정박 선박 군집과 우회 적재 동향을 정리했다.","eSum":"UANI issued an Iran War Shipping Update on 4 June, summarising clusters of vessels loitering near Hormuz and bypass-loading trends.","kImp":"감시 데이터가 위험·물류 판단의 근거가 된다.","eImp":"Monitoring data informs risk and logistics decisions.","url":"https://www.unitedagainstnucleariran.com/blog/iran-war-shipping-update-june-4-2026"},{"code":"GEO","title":"사우디 VLCC, 6월 호르무즈 통항 재개","src":"Discovery Alert","date":"2026-06","kSum":"사우디 VLCC들이 2026년 6월 호르무즈 해협 통항을 재개하며 걸프 원유 수출 정상화 신호를 보냈다. AIS 재가동과 통항 증가가 확인됐다.","eSum":"Saudi VLCCs resumed transiting the Strait of Hormuz in June 2026, signalling a normalisation of Gulf crude exports, with AIS reactivation and rising transits observed.","kImp":"걸프 수출 재개가 원유 물류를 재편한다.","eImp":"Resumed Gulf exports reshape crude logistics.","url":"https://discoveryalert.com.au/saudi-oil-tankers-strait-hormuz-shipping-resumption-2026/"},{"code":"GEO","title":"홍해·파나마 교란이 글로벌 항로 전략 재편","src":"Global Trade Magazine","date":"2026","kSum":"홍해와 파나마운하 교란이 글로벌 해운 항로 전략을 재편하고 있다. 선사들은 항로 다변화·재고 전략·운임 헤지로 대응하고 있다.","eSum":"Red Sea and Panama Canal disruptions are reshaping global shipping route strategies, with carriers responding via route diversification, inventory strategy and rate hedging.","kImp":"복수 길목 동시 교란이 공급망 복원력을 시험한다.","eImp":"Simultaneous chokepoint disruptions test supply-chain resilience.","url":"https://www.globaltrademag.com/the-impact-of-red-sea-and-panama-canal-disruptions-on-global-shipping-strategies/"}]},{"code":"TW","type":"news","kTitle":"Section 17. TradeWinds / Ship Management","eTitle":"Section 17. TradeWinds / Ship Management","items":[{"code":"TW","title":"BSM, 엘레나 판타지두 CPO 선임(6월 1일자)","src":"Bernhard Schulte SM","date":"2026-06","kSum":"베른하르트 슐테(Bernhard Schulte Shipmanagement)가 엘레나 판타지두(Elena Pantazidou)를 최고인사책임자(CPO)로 6월 1일자 선임했다. 인적자원 전략 강화 행보다.","eSum":"Bernhard Schulte Shipmanagement appointed Elena Pantazidou as Chief People Officer effective 1 June 2026, strengthening its HR strategy.","kImp":"인재 전략 강화가 대형 선박관리사 경쟁력의 축이다.","eImp":"People strategy is central to large ship-managers' competitiveness.","url":"https://www.bs-shipmanagement.com/media-centre/"},{"code":"TW","title":"선박관리 추가 합병 가능성 부상","src":"Splash247","date":"2026","kSum":"선박관리 업계에서 추가 합병 가능성이 부상하고 있다. 규모·디지털·연료전환 압력이 통합 논의를 촉진한다.","eSum":"Further consolidation is on the cards in ship management, with scale, digital and fuel-transition pressures fuelling merger talk.","kImp":"통합이 서비스 표준화와 투자여력을 키운다.","eImp":"Consolidation boosts standardisation and investment capacity.","url":"https://splash247.com/further-manager-mergers-on-the-cards/"},{"code":"TW","title":"2025 톱10 선박관리사 순위 발표","src":"Lloyd's List","date":"2026","kSum":"로이즈리스트가 2025년 톱10 선박관리사 순위를 발표했다. 관리 척수·선대 구성·서비스 범위가 평가 기준으로 작용했다.","eSum":"Lloyd's List published its Top 10 shipmanagers 2025 ranking, weighing managed ship counts, fleet composition and service scope.","kImp":"순위가 발주처·선주의 선택 기준에 영향을 준다.","eImp":"Rankings influence owners' and principals' selection criteria.","url":"https://www.lloydslist.com/LL1155778/Top-10-shipmanagers-2025"},{"code":"TW","title":"사모펀드, 선박관리 통합의 새 동력으로","src":"Splash247","date":"2026","kSum":"사모펀드(PE) 자본이 선박관리 통합의 새 동력으로 부상하고 있다. 인수·합병을 통한 규모 확대와 디지털 투자가 가속된다.","eSum":"Private equity is emerging as a new driver of ship-management consolidation, accelerating scale-building M&A and digital investment.","kImp":"PE 유입이 업계 구조와 서비스 모델을 바꾼다.","eImp":"PE inflows reshape industry structure and service models.","url":"https://splash247.com/private-equity-and-shipmanagement/"},{"code":"TW","title":"사모펀드의 선박관리 진입, 신뢰 논쟁 점화","src":"IndexBox","date":"2026","kSum":"사모펀드의 선박관리 진입을 둘러싸고 단기 수익 대 장기 신뢰의 논쟁이 2026년 업계에서 점화됐다. 선주·선원·화주의 신뢰 유지가 과제로 제시됐다.","eSum":"PE's role in ship management has ignited a 2026 industry debate over short-term gains versus long-term trust, with maintaining owner/crew/charterer trust flagged as a challenge.","kImp":"수익성과 신뢰의 균형이 통합 성패를 가른다.","eImp":"Balancing returns and trust will decide consolidation outcomes.","url":"https://www.indexbox.io/blog/private-equity-in-shipmanagement-short-term-gains-vs-long-term-trust/"},{"code":"TW","title":"앵글로이스턴, 오르카AI와 함대 도입 협력","src":"MarineLink","date":"2026","kSum":"앵글로이스턴(Anglo-Eastern)이 오르카AI(Orca AI)와 전략적 파트너십을 맺고 AI 기반 상황인지 플랫폼을 관리 선대에 도입한다. 대형 선박관리사의 첫 공식 AI 도입 약정이다.","eSum":"Anglo-Eastern partnered with Orca AI to roll out an AI-driven situational-awareness platform across its managed fleet - the first major ship-manager to formally commit to such adoption.","kImp":"AI 항법 지원이 기술관리 차별화 요소로 부상한다.","eImp":"AI navigation support becomes a technical-management differentiator.","url":"https://www.marinelink.com/news/maritime/technical-management"}]},{"code":"HOT","type":"news","kTitle":"Section 18. Lloyd's List Hot Topics (Strait of Hormuz)","eTitle":"Section 18. Lloyd's List Hot Topics (Strait of Hormuz)","items":[{"code":"HOT","title":"로이즈리스트: 그림자선단이 호르무즈 통항 주도","src":"Lloyd's List","date":"2026-06","kSum":"로이즈리스트는 이란이 우회 적재를 늘리면서 그림자선단(shadow fleet)이 호르무즈 통항을 주도하고 있다고 보도했다. 규정준수 선박은 위험으로 통항을 자제했다.","eSum":"Lloyd's List reports the shadow fleet dominated Hormuz crossings as Iran ramped up bypass loadings, while compliant ships held back due to risk.","kImp":"제재·위험이 통항 주체를 비규정 선박으로 이동시킨다.","eImp":"Sanctions and risk shift crossings toward non-compliant ships.","url":"https://www.lloydslist.com/LL1156563/Shadow-fleet-dominates-Hormuz-crossings-as-Iran-ramps-up-bypass-loadings"},{"code":"HOT","title":"로이즈리스트: 약 200척 규정준수 탱커 발 묶여","src":"Lloyd's List","date":"2026-06","kSum":"호르무즈 해협 봉쇄로 약 200척의 규정준수 탱커가 걸프에 발이 묶였다고 로이즈리스트가 전했다. 통항 동결이 원유 물류와 운임에 충격을 줬다.","eSum":"Lloyd's List reports around 200 compliant tankers were stranded as the Strait of Hormuz closure froze Gulf traffic, shocking crude logistics and rates.","kImp":"통항 동결이 톤마일·운임 변동성을 키운다.","eImp":"A transit freeze amplifies ton-mile and rate volatility.","url":"https://www.lloydslist.com/LL1156500/Around-200-compliant-tankers-stranded-as-Strait-of-Hormuz-closure-freezes-Gulf-traffic"},{"code":"HOT","title":"호르무즈 '다크 탱커' 통항 동향 2026","src":"Discovery Alert","date":"2026","kSum":"2026년 호르무즈 해협의 '다크 탱커(dark tanker)' 통항 동향이 분석됐다. AIS 비가동 선박의 우회 적재와 통항 패턴이 원유 시장에 영향을 준다.","eSum":"An analysis of dark-tanker traffic in the Strait of Hormuz in 2026 examines how AIS-off vessels' bypass loadings and transit patterns affect the oil market.","kImp":"비가시 선박 동향이 시장 투명성·리스크를 좌우한다.","eImp":"Opaque vessel flows drive market transparency and risk.","url":"https://discoveryalert.com.au/dark-tanker-traffic-strait-hormuz-oil-market-2026/"},{"code":"HOT","title":"2026 호르무즈 해협 위기 개관","src":"Wikipedia","date":"2026","kSum":"2026년 호르무즈 해협 위기는 2월 28일 미·이스라엘의 대이란 군사작전 이후 통항이 급감하며 시작됐다. 탱커 통항이 최대 70% 감소하고 150척 이상이 해협 밖에 정박했다.","eSum":"The 2026 Strait of Hormuz crisis began after the 28 February US/Israel operation against Iran, with tanker traffic falling up to 70% and 150+ ships anchoring outside the strait.","kImp":"위기 경과가 운임·보험·항로 전반을 규정한다.","eImp":"The crisis trajectory defines rates, insurance and routing.","url":"https://en.wikipedia.org/wiki/2026_Strait_of_Hormuz_crisis"}]}]};